import{_ as a,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Tech Talk: Karan Singh - Scale Testing Ceph with 10Billion+ Objects 2020-10-01","description":"","frontmatter":{"title":"Ceph Tech Talk: Karan Singh - Scale Testing Ceph with 10Billion+ Objects 2020-10-01","date":"2020-10-01T00:00:00.000Z","updated":"2020-10-03T00:00:00.000Z","tags":["Ceph","分布式存储","规模测试","性能评估","蓝存储","Red Hat"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Tech_Talk_-_Karan_Singh_-_Scale_Testing_Ceph_with_10Billion+_Objects_2020-10-01.md","filePath":"posts/2020/Ceph_Tech_Talk_-_Karan_Singh_-_Scale_Testing_Ceph_with_10Billion+_Objects_2020-10-01.md","lastUpdated":1780460162000}'),h={name:"posts/2020/Ceph_Tech_Talk_-_Karan_Singh_-_Scale_Testing_Ceph_with_10Billion+_Objects_2020-10-01.md"};function _(n,e,r,o,s,p){return l(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次会议由Red Hat云存储和数据服务业务单元的高级解决方案架构师Karan Singh主持，讨论了Ceph对象存储在处理超过10亿个对象时的规模测试表现。</p><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>规模测试的目的和背景</strong>：</p><ul><li>目的是测试Ceph对象存储在处理大规模数据（10亿个对象）时的性能。</li><li>前期的测试已验证Ceph在1亿个对象时的性能，本次是对其能力的进一步验证。</li></ul></li><li><p><strong>测试环境和配置</strong>：</p><ul><li>使用了6个Red Hat存储节点，每个节点配备53个16TB的旋转设备和6个Intel QLC 3.9设备。</li><li>软件配置包括Red Hat Ceph Storage 4.1，所有守护进程（OSD、Monitor、Manager、RADOS Gateway）都容器化。</li></ul></li><li><p><strong>测试结果和性能分析</strong>：</p><ul><li>Ceph在处理小对象和大对象时都表现出确定性的性能。</li><li>在达到10亿个对象时，系统保持稳定的写入和读取性能。</li><li>模拟硬件故障时，系统展现了良好的容错能力。</li></ul></li><li><p><strong>性能优化的建议</strong>：</p><ul><li>使用多个RADOS Gateway实例以提高性能。</li><li>推荐4%的闪存容量作为BlueStore的元数据存储。</li><li>增加OSD内存目标大小以提高性能。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>确认了Ceph对象存储在处理大规模数据时的稳定性和性能。</li><li>确定了设计和部署大规模Ceph集群时的最佳实践和配置建议。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>发布完整的测试报告，供社区和客户参考。</li><li>继续监控和优化Ceph在大规模数据处理中的性能。</li></ul><h4 id="其他信息" tabindex="-1">其他信息 <a class="header-anchor" href="#其他信息" aria-label="Permalink to &quot;其他信息&quot;">​</a></h4><ul><li>讨论了BlueStore的配置和优化，以及如何更有效地使用闪存存储。</li><li>提供了关于如何根据测试结果进行集群规模估算的指导。</li></ul><p>本次会议为Ceph对象存储在大规模数据处理中的应用提供了宝贵的性能数据和优化建议，有助于推动Ceph在企业级存储解决方案中的进一步应用。</p>',12)])])}const u=a(h,[["render",_]]);export{d as __pageData,u as default};
